const norm=v=>(v||'').toLocaleLowerCase('es').normalize('NFD').replace(/[\u0300-\u036f]/g,'');
function filterProducts(){if(!searchInput||!emptyState)return;const q=norm(searchInput.value.trim());let n=0;cards.forEach(c=>{const ok=(activeCategory==='all'||c.dataset.category===activeCategory)&&(!q||norm(`${c.dataset.name||''} ${c.textContent||''}`).includes(q));c.hidden=!ok;if(ok)n++;});emptyState.hidden=n!==0;}
